<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$status=(string)($_GET['status']??'');$priority=(string)($_GET['priority']??'');$q=trim((string)($_GET['q']??''));$allowedStatus=['new','contacted','proposal','won','lost'];$allowedPriority=['low','normal','high'];$where=[];$params=[];if(in_array($status,$allowedStatus,true)){$where[]='status=?';$params[]=$status;}if(in_array($priority,$allowedPriority,true)){$where[]='priority=?';$params[]=$priority;}if($q!==''){$where[]='(name LIKE ? OR email LIKE ? OR company LIKE ? OR service LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}$sql='SELECT * FROM leads'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC';$stmt=$db->prepare($sql);$stmt->execute($params);$leads=$stmt->fetchAll();$counts=$db->query("SELECT status,COUNT(*) total FROM leads GROUP BY status")->fetchAll();$countMap=array_fill_keys($allowedStatus,0);foreach($counts as $c)$countMap[$c['status']]=(int)$c['total'];$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Leads | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>.stat{border-radius:18px}.lead-card{border:0;border-radius:18px}.high{border-left:5px solid #dc3545}.status{font-size:.72rem;text-transform:uppercase;font-weight:800;letter-spacing:.05em}</style></head><body class="bg-light"><main class="container py-5"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h2 mb-1">Lead Management</h1><p class="text-muted mb-0">Website enquiries and sales pipeline.</p></div><a href="index.php" class="btn btn-outline-dark">Dashboard</a></div><div class="row g-3 mb-4"><?php foreach($allowedStatus as $s):?><div class="col-6 col-lg"><div class="card stat border-0 shadow-sm p-3"><small class="text-muted text-uppercase"><?=$esc($s)?></small><strong class="fs-3"><?=$countMap[$s]?></strong></div></div><?php endforeach;?></div><form class="card border-0 shadow-sm p-3 mb-4"><div class="row g-2"><div class="col-lg-5"><input class="form-control" name="q" value="<?=$esc($q)?>" placeholder="Search name, email, company or service"></div><div class="col-lg-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach($allowedStatus as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></div><div class="col-lg-3"><select class="form-select" name="priority"><option value="">All priorities</option><?php foreach($allowedPriority as $p):?><option value="<?=$p?>" <?=$priority===$p?'selected':''?>><?=ucfirst($p)?></option><?php endforeach;?></select></div><div class="col-lg-1"><button class="btn btn-dark w-100">Go</button></div></div></form><div class="row g-3"><?php foreach($leads as $lead):?><div class="col-12"><article class="card lead-card shadow-sm <?=$lead['priority']==='high'?'high':''?>"><div class="card-body"><div class="d-flex flex-wrap justify-content-between gap-3"><div><h2 class="h5 mb-1"><?=$esc($lead['name'])?></h2><div class="text-muted small"><?=$esc($lead['email'])?><?php if($lead['phone']):?> · <?=$esc($lead['phone'])?><?php endif;?></div></div><div class="text-end"><span class="badge text-bg-secondary status"><?=$esc($lead['status'])?></span> <span class="badge text-bg-<?=$lead['priority']==='high'?'danger':($lead['priority']==='low'?'light':'dark')?>"><?=$esc($lead['priority'])?></span></div></div><div class="row mt-3 g-3"><div class="col-md-3"><small class="text-muted d-block">Service</small><strong><?=$esc($lead['service']?:'—')?></strong></div><div class="col-md-3"><small class="text-muted d-block">Company</small><strong><?=$esc($lead['company']?:'—')?></strong></div><div class="col-md-3"><small class="text-muted d-block">Budget</small><strong><?=$esc($lead['budget']?:'—')?></strong></div><div class="col-md-3"><small class="text-muted d-block">Received</small><strong><?=$esc(date('d M Y H:i',strtotime($lead['created_at'])))?></strong></div></div><p class="mt-3 mb-0 text-secondary"><?=nl2br($esc($lead['message']))?></p><div class="mt-3"><a class="btn btn-sm btn-dark" href="lead.php?id=<?=$esc($lead['id'])?>">Open Lead</a></div></div></article></div><?php endforeach;if(!$leads):?><div class="col-12"><div class="alert alert-info">No leads match your filters.</div></div><?php endif;?></div></main></body></html>